//! Protocol Buffer generated types
//!
//! This module includes code generated from firmware/common/proto/*.proto
//! DO NOT manually define protocol types - they are generated by prost.
//!
//! To add new messages or modify existing ones:
//! 1. Edit firmware/common/proto/*.proto
//! 2. Run `cargo build` - prost will regenerate this code
//! 3. Update code that uses the types

/// Config protocol types (generated from config.proto)
#[allow(dead_code, clippy::enum_variant_names)]
pub mod config {
    include!(concat!(env!("OUT_DIR"), "/domes.config.rs"));

    impl Feature {
        /// Get user-friendly name for CLI display
        pub fn cli_name(&self) -> &'static str {
            match self {
                Feature::Unknown => "unknown",
                Feature::LedEffects => "led-effects",
                Feature::BleAdvertising => "ble",
                Feature::Wifi => "wifi",
                Feature::EspNow => "esp-now",
                Feature::Touch => "touch",
                Feature::Haptic => "haptic",
                Feature::Audio => "audio",
            }
        }

        /// Parse from CLI input string
        pub fn from_cli_name(s: &str) -> Option<Feature> {
            match s.to_lowercase().as_str() {
                "led-effects" | "led" | "leds" => Some(Feature::LedEffects),
                "ble" | "bluetooth" | "ble-advertising" => Some(Feature::BleAdvertising),
                "wifi" | "wi-fi" => Some(Feature::Wifi),
                "esp-now" | "espnow" => Some(Feature::EspNow),
                "touch" => Some(Feature::Touch),
                "haptic" | "haptics" => Some(Feature::Haptic),
                "audio" | "sound" => Some(Feature::Audio),
                _ => None,
            }
        }
    }

    impl std::fmt::Display for Feature {
        fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
            write!(f, "{}", self.cli_name())
        }
    }

    impl std::str::FromStr for Feature {
        type Err = String;

        fn from_str(s: &str) -> Result<Self, Self::Err> {
            Self::from_cli_name(s).ok_or_else(|| format!("Unknown feature: {}", s))
        }
    }

    impl MsgType {
        /// Convert to u8 for frame encoding
        pub fn as_u8(&self) -> u8 {
            *self as i32 as u8
        }
    }

    impl SystemMode {
        /// Get user-friendly name for CLI display
        pub fn cli_name(&self) -> &'static str {
            match self {
                SystemMode::Booting => "booting",
                SystemMode::Idle => "idle",
                SystemMode::Triage => "triage",
                SystemMode::Connected => "connected",
                SystemMode::Game => "game",
                SystemMode::Error => "error",
            }
        }

        /// Parse from CLI input string
        pub fn from_cli_name(s: &str) -> Option<SystemMode> {
            match s.to_lowercase().as_str() {
                "booting" => Some(SystemMode::Booting),
                "idle" => Some(SystemMode::Idle),
                "triage" => Some(SystemMode::Triage),
                "connected" => Some(SystemMode::Connected),
                "game" => Some(SystemMode::Game),
                "error" => Some(SystemMode::Error),
                _ => None,
            }
        }
    }

    impl ResetReason {
        /// Get a stable, user-facing reset reason.
        pub fn cli_name(&self) -> &'static str {
            match self {
                ResetReason::Unknown => "unknown",
                ResetReason::PowerOn => "power-on",
                ResetReason::ExternalPin => "external pin",
                ResetReason::Software => "software restart",
                ResetReason::Panic => "panic",
                ResetReason::InterruptWatchdog => "interrupt watchdog",
                ResetReason::TaskWatchdog => "task watchdog",
                ResetReason::Watchdog => "watchdog",
                ResetReason::DeepSleep => "deep-sleep wake",
                ResetReason::Brownout => "brownout",
                ResetReason::Sdio => "SDIO",
                ResetReason::Usb => "USB",
                ResetReason::Jtag => "JTAG",
                ResetReason::Efuse => "eFuse error",
                ResetReason::PowerGlitch => "power glitch",
                ResetReason::CpuLockup => "CPU lockup",
            }
        }
    }

    impl std::fmt::Display for SystemMode {
        fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
            write!(f, "{}", self.cli_name())
        }
    }

    impl std::str::FromStr for SystemMode {
        type Err = String;

        fn from_str(s: &str) -> Result<Self, Self::Err> {
            Self::from_cli_name(s).ok_or_else(|| format!("Unknown mode: {}", s))
        }
    }
}

/// Portable peer/drill semantic types (generated from peer_drill.proto).
#[allow(dead_code)]
pub mod peer_drill {
    include!(concat!(env!("OUT_DIR"), "/domes.peer_drill.rs"));

    #[cfg(test)]
    mod tests {
        use super::peer_message::Payload;
        use super::*;
        use prost::Message;

        const ARM_FIXTURE: &[u8] = &[
            0x08, 0x01, 0x12, 0x06, 0x94, 0xA9, 0x90, 0x0A, 0xEB, 0xC0, 0x1D, 0x44, 0x33, 0x22,
            0x11, 0x72, 0x0A, 0x0D, 0xD4, 0xC3, 0xB2, 0xA1, 0x10, 0xB8, 0x17, 0x18, 0x03,
        ];

        #[test]
        fn generated_oneof_exposes_exactly_ten_peer_variants() {
            let variants = [
                Payload::Beacon(Beacon {}),
                Payload::Ping(Ping {}),
                Payload::Pong(Pong {}),
                Payload::JoinGame(JoinGame {}),
                Payload::ArmTouch(ArmTouch::default()),
                Payload::SetColor(SetColor::default()),
                Payload::StopAll(StopAll {}),
                Payload::SimulateTouch(SimulateTouch::default()),
                Payload::TouchEvent(TouchEvent::default()),
                Payload::TimeoutEvent(TimeoutEvent::default()),
            ];

            assert_eq!(variants.len(), 10);
        }

        #[test]
        fn generated_fixed32_arm_fixture_round_trips_exactly() {
            let message = PeerMessage {
                protocol_version: 1,
                sender_mac: vec![0x94, 0xA9, 0x90, 0x0A, 0xEB, 0xC0],
                sender_timestamp_us: 0x1122_3344,
                payload: Some(Payload::ArmTouch(ArmTouch {
                    round_token: 0xA1B2_C3D4,
                    timeout_ms: 3000,
                    feedback_mode: FeedbackMode::LedAndAudio.into(),
                })),
            };

            assert_eq!(message.encode_to_vec(), ARM_FIXTURE);
            let decoded = PeerMessage::decode(ARM_FIXTURE).expect("fixture must decode");
            assert_eq!(decoded.protocol_version, 1);
            assert_eq!(decoded.sender_mac.len(), 6);
            let Some(Payload::ArmTouch(arm)) = decoded.payload else {
                panic!("fixture must select arm_touch");
            };
            assert_eq!(arm.round_token, 0xA1B2_C3D4);
            assert_eq!(arm.timeout_ms, 3000);
            assert_eq!(arm.feedback_mode, FeedbackMode::LedAndAudio as i32);
        }
    }
}

